INSERT INTO state_legal_rules (jurisdiction_id,source_id,rule_code,domain_code,rule_title,rule_statement,trigger_condition,mandatory,confidence_score) SELECT j.id,s.id,'EK-LAND-001','LAND_TENURE','State land administration and transaction pathway','Land administration records and Certificate of Occupancy processing should be handled through the state land administration framework and its published procedures.','Any asset claimed to be within Ekiti State and presented for formal land transaction or title verification.',true,97 FROM state_legal_jurisdictions j JOIN state_legal_sources s ON s.jurisdiction_id=j.id AND s.title='CoFO Processing Approved Fees Order' WHERE j.state_code='EK' AND j.lga_code IS NULL ON CONFLICT (jurisdiction_id,rule_code) DO NOTHING;
INSERT INTO state_legal_rules (jurisdiction_id,source_id,rule_code,domain_code,rule_title,rule_statement,trigger_condition,mandatory,confidence_score) SELECT j.id,s.id,'EK-PLAN-001','PLANNING','Planning permit and development control','Ekiti State planning authorities process planning permits and enforce approved development plans, layouts, density, setbacks and related development controls.','Any proposed physical development or change of use requiring planning approval.',true,98 FROM state_legal_jurisdictions j JOIN state_legal_sources s ON s.jurisdiction_id=j.id AND s.title='Ministry of Housing and Urban Development functions and planning permits' WHERE j.state_code='EK' AND j.lga_code IS NULL ON CONFLICT (jurisdiction_id,rule_code) DO NOTHING;
INSERT INTO state_legal_rules (jurisdiction_id,source_id,rule_code,domain_code,rule_title,rule_statement,trigger_condition,mandatory,confidence_score) SELECT j.id,s.id,'EK-PLAN-002','LAND_USE_CLEARANCE','Land-use clearance trigger','The published Building Regulations state that specified developments must obtain land-use clearance before development is carried out; developments over 5,000 square metres require layout approval before development is proposed.','Development falls within a listed schedule or exceeds the stated area threshold.',true,97 FROM state_legal_jurisdictions j JOIN state_legal_sources s ON s.jurisdiction_id=j.id AND s.title='Ekiti State Building Regulations 2017' WHERE j.state_code='EK' AND j.lga_code IS NULL ON CONFLICT (jurisdiction_id,rule_code) DO NOTHING;
INSERT INTO state_legal_rules (jurisdiction_id,source_id,rule_code,domain_code,rule_title,rule_statement,trigger_condition,mandatory,confidence_score) SELECT j.id,s.id,'EK-INV-001','INVESTMENT_SCREENING','Large-scale agricultural investment screening','The FRILIA toolkit describes an investment approval pathway beginning with initial inquiry, KYC/due diligence and stakeholder engagement for large-scale agricultural investments.','Large-scale agricultural investment is proposed in Ekiti State.',true,95 FROM state_legal_jurisdictions j JOIN state_legal_sources s ON s.jurisdiction_id=j.id AND s.title='FRILIA Land and Agriculture Investment Approval Toolkit' WHERE j.state_code='EK' AND j.lga_code IS NULL ON CONFLICT (jurisdiction_id,rule_code) DO NOTHING;
INSERT INTO state_legal_rules (jurisdiction_id,source_id,rule_code,domain_code,rule_title,rule_statement,trigger_condition,mandatory,confidence_score) SELECT j.id,s.id,'EK-GEO-001','GEOSPATIAL','Survey and geospatial integrity','The State has been implementing statewide survey and GIS mapping to improve land administration and geospatial reliability; the platform should treat authoritative survey evidence and coordinate provenance as distinct verification requirements.','Asset is being represented with boundaries, coordinates, parcel identity or survey claims.',true,94 FROM state_legal_jurisdictions j JOIN state_legal_sources s ON s.jurisdiction_id=j.id AND s.title='CoFO Processing Approved Fees Order' WHERE j.state_code='EK' AND j.lga_code IS NULL ON CONFLICT (jurisdiction_id,rule_code) DO NOTHING;
